      <nav class="history-items" aria-label="历史会话">
        <button v-for="item in localDrafts" :key="item.key" :class="{active:currentKey===item.key}" @click="currentKey=item.key;historyOpen=false"><strong>{{ item.slot.pending?.question || item.slot.draft.question || '待确认的会话' }}</strong><small>{{ item.slot.submitting?'请求提交中':item.slot.uncertain?'请求尚未确认':'未受理草稿，仅本页保留' }}</small></button>
        <button v-for="item in history" :key="item.id" :class="{active:currentKey===item.id}" @click="openConversation(item.id)">
          <strong>{{ item.title || '未命名会话' }}</strong><small>{{ item.expertName || '已保存分析' }} · {{ date(item.updatedAt || item.createdAt) }}</small>
          <span v-if="slots[item.id]?.running" class="working">正在分析</span>
        </button>
      </nav>
      <el-empty v-if="!history.length&&!historyLoading" description="首次发送后保存在这里" :image-size="48" />
      <el-button v-if="history.length<historyTotal" :loading="historyLoading" @click="loadHistory(false)">加载更多（{{ history.length }}/{{ historyTotal }}）</el-button>
      <footer>历史读取当时保存的结果。<br>未发送草稿在本次页面中保留。</footer>
    </aside>

    <section class="chat-pane">
      <header class="chat-heading"><div><el-button text class="mobile-only" @click="historyOpen=true">☰ 会话</el-button><h1>{{ active.research?.title || '新会话' }}</h1><p>选择专家和分析事项，明确范围后运行；历史结果保留原版本。</p></div><el-button v-if="selectedRun" @click="resultOpen=true">查看本轮结果</el-button></header>
      <div v-if="loadError" class="notice error" role="alert">{{ loadError }}</div>
      <div v-if="resourcesError" class="notice error" role="alert">专家与业务任务暂时无法加载：{{ resourcesError }} <el-button link :loading="resourcesLoading" @click="load">重试加载专家</el-button></div>
      <div v-if="active.error" class="notice error" role="alert">{{ active.error }} <el-button v-if="active.pending" link @click="recover">查询原请求</el-button></div>
      <div v-if="active.notice" class="notice" role="status">{{ active.notice }}</div>
      <section ref="messagesArea" class="messages" aria-label="会话消息">
        <div v-if="!turns.length" class="welcome"><span class="welcome-icon">问</span><h2>{{ selectedExpert?selectedExpert.name:'从一个具体的管理问题开始' }}</h2><p v-if="selectedExpert?.published?.content.welcomeMessage" class="welcome-message">{{ selectedExpert.published.content.welcomeMessage }}</p><p v-else>用下方 ＋ 选择专家。可执行任务读取114测试数据，缺项和未知会在结果中说明。</p><p class="muted">模型未接通时，选择业务任务并填写范围；文字作为背景保存。</p></div>
        <article v-for="(turn,index) in turns" :key="turn.id || index" class="message-turn" :class="{selected:active.selected===index}">
          <div class="user-message"><small>本轮问题 · {{ date(turn.createdAt) }}</small><p>{{ turn.question || '按所选范围分析' }}</p></div>
          <button class="expert-message" @click="active.selected=index;resultOpen=true">
            <div class="message-author"><span>{{ turn.expert?.name || turn.expertName || catalog.experts.find(e=>e.id===turn.expertId)?.name || active.research?.expertName || '历史专家' }}</span><small>{{ turn.expert?.version || turn.expertVersion ? `v${turn.expert?.version || turn.expertVersion}` : '历史记录未保存逐轮版本' }}</small><el-tag size="small" effect="plain">{{ stateLabel(turn.execution?.state || turn.state || turn.status) }}</el-tag></div>
            <p>{{ turn.summary || turn.result?.summary || turn.error || '查看本轮保存记录' }}</p><span class="message-action">查看结果与依据 →</span>
          </button>
          <p v-if="turn.referenceState==='invalid'" class="notice error">来源已失效，原结果保留。{{ turn.referenceReason }}</p>
        </article>
        <div v-if="active.running" class="notice progress" role="status"><span>{{ executionProgress(active.execution) }}</span><el-button size="small" :disabled="!executionId(active.execution)||finalStates.has(active.execution?.state||'')" @click="cancel">停止本轮</el-button></div>
        <section v-if="clarification" class="clarification"><h3>补充一个必要条件</h3><p>{{ clarification.question }}</p><el-select v-if="clarification.options?.length" v-model="active.answer" placeholder="选择答案"><el-option v-for="option in clarification.options" :key="typeof option==='string'?option:option.id" :value="typeof option==='string'?option:option.id" :label="typeof option==='string'?option:option.label" /></el-select><el-input v-else v-model="active.answer" placeholder="补充所需条件" /><el-button type="primary" :disabled="!active.answer.trim()||active.running" @click="answerClarification">由原专家继续核验</el-button></section>
        <el-button v-if="canRetry" @click="retry">由原专家按原范围重试</el-button>
      </section>

      <section class="composer" aria-label="下一轮问题">
        <div v-if="draft.source" class="source-reference"><div><b>引用AI简报的保存结果</b><span>{{ draft.source.name || draft.source.publicationId }} · {{ draft.source.objectName || draft.source.objectId || '本范围' }}</span></div><el-button text @click="clearSource">移除引用</el-button><el-button text @click="returnToBriefing">返回原简报</el-button></div>
        <div class="composer-controls"><el-button circle aria-label="选择下一轮专家" :disabled="active.running" @click="pickerOpen=true">＋</el-button><el-tag v-if="selectedExpert" closable :disable-transitions="true" @close="removeExpert">{{ selectedExpert.name }} · {{ nextVersionLabel }}</el-tag><span v-else class="muted">先选择本轮专家</span><el-button v-if="canUpgrade" text :disabled="active.running" @click="upgradeExpert">本轮采用已发布新版本</el-button></div>
        <template v-if="selectedExpert"><div class="expert-context"><span>{{ selectedExpert.published?.content.summary||selectedExpert.summary }}</span><el-button text @click="capabilityExpert=selectedExpert">用途与适用边界</el-button></div>
          <div v-if="draft.source" class="reference-mode"><el-radio-group v-model="draft.readMode" :disabled="active.running"><el-radio value="saved">说明原保存结果</el-radio><el-radio value="live">更新当前数据（新一轮查询）</el-radio></el-radio-group><p>原结果的时间、范围与来源保留；更新数据会另存一轮。</p></div>
          <div v-if="draft.readMode!=='saved'" class="input-controls"><el-radio-group v-model="draft.mode" :disabled="active.running"><el-radio value="selected_task">业务任务</el-radio><el-radio value="question" :disabled="!modelAvailable">直接提问</el-radio></el-radio-group><el-select v-if="draft.mode==='selected_task'" v-model="draft.taskId" placeholder="选择分析事项" :disabled="active.running" @change="changeTask"><el-option v-for="task in availableTasks" :key="task.taskId" :label="task.title" :value="task.taskId" :disabled="!task.available" /></el-select><span v-if="!modelAvailable" class="muted">当前使用已登记业务任务；直接提问尚未开放。</span></div>
          <ScopeInputs v-if="draft.readMode!=='saved'&&draft.mode==='selected_task'&&selectedTask" v-model="draft.input" :schema="selectedTask.inputSchema" :options="options" :disabled="active.running" :loading="optionsLoading" :failed="!!optionsError" :course-loading="coursesLoading" :course-error="coursesError" compact />
          <p v-if="optionsError||coursesError" class="error">{{ optionsError || coursesError }} <el-button link @click="loadOptions();loadCourses()">重试选项</el-button></p>
          <p v-if="selectedTask&&!selectedTask.available" class="muted">{{ selectedTask.reason }}</p>
          <p v-if="problems.length" class="muted">{{ problems.join('；') }}</p>
        </template>
        <el-input v-model="draft.question" type="textarea" :rows="2" :autosize="{minRows:2,maxRows:6}" maxlength="1500" :placeholder="draft.mode==='question'?'输入管理问题，Ctrl+Enter发送':'可选：补充背景；不填写也可运行所选分析事项'" aria-label="本轮问题" @keydown="onComposerKey" />
        <div class="send-row"><small>{{ sendBlockReason || (draft.readMode==='saved'?'发送后核验原结果引用，说明当时事实。':'数据按当前身份权限查询，运行后保存本轮。') }}</small><el-button type="primary" :loading="active.submitting" :disabled="!canSend" @click="send">{{ draft.readMode==='saved'?'说明保存结果':draft.mode==='selected_task'?'运行分析':'发送' }}</el-button></div>
      </section>
    </section>

    <aside v-if="selectedRun" class="result-pane"><header><h2>{{ active.selected>=0?`第${active.selected+1}轮结果`:'结果与数据' }}</h2><span v-if="latestValid>=0&&active.selected!==latestValid"><el-button link @click="active.selected=latestValid">最近有效结果在第{{ latestValid+1 }}轮</el-button></span></header><div class="result-scroll"><RunResult v-if="selectedRun" :key="selectedRun.id" :run="selectedRun" :options="options" :version="selectedRun.expert?.version || selectedRun.expertVersion" mode="research" :allow-course-analysis="selectedRun.input?.taskId==='C-PERFORMANCE'" @inspect-course="prepareCourse" @show-issues="issuesOpen=true" /><el-empty v-else description="发送后在这里查看事实、来源和保存证据" :image-size="70" /></div></aside>
    <el-drawer v-model="resultOpen" title="本轮结果与依据" size="min(760px,94vw)" class="result-drawer"><RunResult v-if="selectedRun" :run="selectedRun" :options="options" :version="selectedRun.expert?.version || selectedRun.expertVersion" mode="research" :allow-course-analysis="selectedRun.input?.taskId==='C-PERFORMANCE'" @inspect-course="prepareCourse" @show-issues="issuesOpen=true" /></el-drawer>
    <el-drawer v-model="issuesOpen" title="待明确事项" size="min(760px,94vw)"><ResearchIssues v-if="active.research" :research-id="active.research.id" :refresh="turns.length" @recheck="prepareRecheck" /></el-drawer>
    <el-dialog v-model="pickerOpen" title="选择本轮专家" width="min(850px,94vw)" append-to-body>
      <p class="muted">先查看当前能力，再选择。每轮保存实际使用的专家与版本。</p>
      <p v-if="resourcesLoading" role="status">正在加载专家与业务任务…</p>
      <div v-else-if="resourcesError" class="notice error" role="alert">{{ resourcesError }} <el-button link @click="load">重试加载专家</el-button></div>
      <template v-else>
        <h3 class="picker-heading">当前可用（{{ usableExperts.length }}）</h3>
        <div class="expert-picker"><article v-for="expert in usableExperts" :key="expert.id" class="expert-choice" :class="{chosen:draft.expertId===expert.id}"><b>{{ expert.name }}</b><p>{{ expert.published?.content.summary||expert.summary }}</p><p class="task-preview">{{ tasks.filter(t=>t.expertId===expert.id&&t.available).map(t=>t.title).join('；')||'已接通模型问答' }}</p><span>已发布 v{{ expert.published?.version }}</span><div class="picker-actions"><el-button text @click="capabilityExpert=expert">查看能力</el-button><el-button type="primary" plain :aria-label="`选择${expert.name}`" @click="selectExpert(expert)">选择专家</el-button></div></article></div>
        <el-empty v-if="!usableExperts.length" description="当前身份暂无可执行专家" :image-size="55" />
        <details v-if="unavailableExperts.length" class="unavailable-experts"><summary>尚未开放的业务专家（{{ unavailableExperts.length }}）</summary><article v-for="expert in unavailableExperts" :key="expert.id"><b>{{ expert.name }}</b><p>{{ unavailableReason(expert) }}</p><el-button text @click="capabilityExpert=expert">查看能力与缺项</el-button></article></details>
      </template>
      <template #footer><el-button @click="pickerOpen=false">取消</el-button></template>
    </el-dialog>
    <el-dialog :model-value="!!capabilityExpert" title="专家能力与适用边界" width="min(820px,94vw)" append-to-body @close="capabilityExpert=null"><ResourceOverview v-if="capabilityExpert" kind="experts" :content="capabilityExpert.published?.content||capabilityExpert.draft.content" :tasks="tasks.filter(t=>t.expertId===capabilityExpert?.id)" /><template #footer><el-button @click="capabilityExpert=null">关闭</el-button><el-button v-if="capabilityExpert&&canSelectExpert(capabilityExpert)" type="primary" @click="selectExpert(capabilityExpert);capabilityExpert=null">使用此专家</el-button></template></el-dialog>
  </main>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { authStore } from '@/store/auth'
import { expertResourcesApi as api, explanationStateLabel, type ConversationRequest } from '@/api/aiDecision/expertResources'
import type { BusinessTask, ExpertExecution, ExpertModel, ExpertResource, ResourceCatalog, ResourceOptions, ResourceResearch, ResourceRun } from '@/types/expertResources'
import ScopeInputs from '../expert-resources/ScopeInputs.vue'
import ResourceOverview from '../expert-resources/ResourceOverview.vue'
import RunResult from '../expert-resources/RunResult.vue'
import ResearchIssues from '../expert-resources/ResearchIssues.vue'
import { inputProblems } from '../expert-resources/presentation'

interface Draft {expertId:string;taskId:string;mode:'selected_task'|'question';input:Record<string,unknown>;question:string;readMode:'live'|'saved';upgradeToVersion?:string;originalTurnId?:string;source?:Record<string,any>}
interface Slot {research:ResourceResearch|null;draft:Draft;selected:number;execution:ExpertExecution|null;pending:ConversationRequest|null;running:boolean;submitting:boolean;uncertain:boolean;error:string;notice:string;answer:string}
const makeDraft=():Draft=>({expertId:'',taskId:'',mode:'selected_task',input:{},question:'',readMode:'live'})
const makeSlot=():Slot=>({research:null,draft:makeDraft(),selected:-1,execution:null,pending:null,running:false,submitting:false,uncertain:false,error:'',notice:'',answer:''})
const route=useRoute(),router=useRouter(),slots=reactive<Record<string,Slot>>({'new':makeSlot()}),currentKey=ref('new')
const active=computed(()=>slots[currentKey.value] || slots.new!),draft=computed(()=>active.value.draft)
const catalog=ref<ResourceCatalog>({experts:[],skills:[],mcps:[]}),tasks=ref<BusinessTask[]>([]),models=ref<ExpertModel[]>([]),options=ref<ResourceOptions>({plans:[],semesters:[],colleges:[],courses:[]})
const history=ref<ResourceResearch[]>([]),historyTotal=ref(0),historySearch=ref(''),historyLoading=ref(false),historyError=ref(''),loadError=ref(''),optionsError=ref(''),optionsLoading=ref(false),coursesLoading=ref(false),coursesError=ref('')
const resourcesError=ref(''),resourcesLoading=ref(false)
const capabilityExpert=ref<ExpertResource|null>(null)
const pickerOpen=ref(false),resultOpen=ref(false),historyOpen=ref(false),issuesOpen=ref(false),messagesArea=ref<HTMLElement|null>(null)
const selectedExpert=computed(()=>catalog.value.experts.find(e=>e.id===draft.value.expertId)),availableTasks=computed(()=>tasks.value.filter(t=>t.expertId===draft.value.expertId)),selectedTask=computed(()=>availableTasks.value.find(t=>t.taskId===draft.value.taskId))
const turns=computed<ResourceRun[]>(()=>active.value.research?.turns?.map(t=>{const e=active.value.execution,expert=t.expert?.legacy&&e&&e.turnId===t.id?{id:e.expertId,name:catalog.value.experts.find(item=>item.id===e.expertId)?.name,version:e.expertVersion}:t.expert;return {...t,...t.run,expert,status:t.run?.status||t.status||t.execution?.state||'blocked'}})||[])
const localDrafts=computed(()=>Object.entries(slots).filter(([key,slot])=>key.startsWith('pending:')&&!slot.research).map(([key,slot])=>({key,slot})))
const selectedRun=computed(()=>turns.value[active.value.selected]),latestValid=computed(()=>{for(let i=turns.value.length-1;i>=0;i--)if(turns.value[i]?.resultId||turns.value[i]?.result?.resultId||turns.value[i]?.execution?.resultId)return i;return -1})
const previousExpert=computed(()=>{const last=turns.value.at(-1);return (last?.expert?.id||last?.expertId)===draft.value.expertId?last?.expert:undefined})
const nextVersionLabel=computed(()=>draft.value.upgradeToVersion?`v${draft.value.upgradeToVersion}`:previousExpert.value?.version?`沿用 v${previousExpert.value.version}`:selectedExpert.value?.published?`v${selectedExpert.value.published.version}`:'未发布')
const canUpgrade=computed(()=>previousExpert.value?.version&&selectedExpert.value?.published?.version!==previousExpert.value.version&&!draft.value.upgradeToVersion)
const modelAvailable=computed(()=>!!selectedExpert.value&&models.value.some(m=>m.id===selectedExpert.value?.published?.content.modelId&&m.enabled!==false&&m.available!==false))
const businessExperts=computed(()=>catalog.value.experts.filter(expert=>tasks.value.some(task=>task.expertId===expert.id)||(expert.published?.content||expert.draft.content).executionMode==='llm'))
const usableExperts=computed(()=>businessExperts.value.filter(canSelectExpert)),unavailableExperts=computed(()=>businessExperts.value.filter(expert=>!canSelectExpert(expert)))
function canSelectExpert(expert:ExpertResource){return canRunExpert(expert)&&(tasks.value.some(task=>task.expertId===expert.id&&task.available)||models.value.some(model=>model.id===expert.published?.content.modelId&&model.enabled!==false&&model.available!==false))}
function unavailableReason(expert:ExpertResource){if(!expert.enabled)return '已停用；历史结果仍可阅读。';if(!expert.published)return '尚未发布，当前不能运行。'+(expert.draft.content.missingEvidence?.[0]||'');return expert.readiness?.runReasons?.join('；')||tasks.value.find(task=>task.expertId===expert.id&&!task.available)?.reason||'当前尚无可执行任务或已接通问答能力。'}
const problems=computed(()=>draft.value.readMode==='saved'||draft.value.mode==='question'?[]:inputProblems(selectedTask.value?.inputSchema,draft.value.input))
const sendBlockReason=computed(()=>{
  if(active.value.submitting)return '正在提交本轮，请稍候。'
  if(active.value.running)return '本轮进行中，可编辑下一轮草稿或切换会话。'
  if(active.value.uncertain)return '原请求状态尚未确认，请先查询原请求。'
  if(resourcesLoading.value)return '正在核对专家与业务任务，请稍候。'
  if(resourcesError.value)return '专家与业务任务加载失败，请重试加载专家。'
  if(!selectedExpert.value)return '请用 ＋ 选择本轮专家。'
  if(!canRunExpert(selectedExpert.value))return selectedExpert.value.readiness?.runReasons?.join('；')||'当前专家暂不可执行。'
  if(draft.value.readMode==='saved')return !draft.value.source?'请先选择要说明的保存结果。':!draft.value.question.trim()?'请填写要说明的问题。':''
  if(draft.value.mode==='question')return !modelAvailable.value?'本专家真实模型尚未接通，请选择业务任务。':!draft.value.question.trim()?'请填写本轮问题。':''
  if(!selectedTask.value?.available)return selectedTask.value?.reason||'请选择可执行的业务任务。'
  if(problems.value.length)return problems.value.join('；')
  if(optionsLoading.value||coursesLoading.value)return '正在加载可选范围，请稍候。'
  return ''
})
const canSend=computed(()=>!sendBlockReason.value)
const clarification=computed(()=>active.value.execution?.clarification||active.value.execution?.outcome?.clarification||active.value.execution?.outcome?.result?.clarification)
const canRetry=computed(()=>!active.value.running&&!active.value.uncertain&&!!active.value.pending&&['failed','blocked','cancelled'].includes(active.value.execution?.state||''))
const timers=new Map<Slot,ReturnType<typeof setTimeout>>();let epoch=0,historyEpoch=0,coursesEpoch=0,searchTimer:ReturnType<typeof setTimeout>|undefined
const finalStates=new Set(['needs_input','completed','partial','blocked','failed','cancelled'])
function date(value?:string){if(!value)return '';const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})}
function stateLabel(value?:string){return ({queued:'等待执行',running:'正在分析',needs_input:'需要补充',completed:'已完成',passed:'已完成',partial:'部分结果',blocked:'条件未满足',failed:'执行失败',cancelled:'已停止'} as Record<string,string>)[value||'']||'已保存回复'}
function executionProgress(value:ExpertExecution|null){if(value&&finalStates.has(value.state)&&value.workerFinished===false)return `${stateLabel(value.state)} · ${explanationStateLabel(value.explanationState)}；工作进程尚未结束，请稍候。`;return `${stateLabel(value?.state||'queued')} · ${value?.summary||'正在核对范围和真实数据'}`}
function executionId(value:ExpertExecution|null){return value?.executionId||value?.id||''}
function canRunExpert(e:ExpertResource){return !!e.published&&e.enabled&&e.readiness?.canRun!==false}
function newConversation(){currentKey.value='new';historyOpen.value=false;loadError.value=''}
function selectExpert(expert:ExpertResource){if(active.value.running||!canSelectExpert(expert))return;const changed=draft.value.expertId!==expert.id;draft.value.expertId=expert.id;draft.value.upgradeToVersion=undefined;draft.value.originalTurnId=undefined;if(changed){draft.value.taskId=tasks.value.find(t=>t.expertId===expert.id&&t.available)?.taskId||'';draft.value.input={};draft.value.mode=draft.value.taskId?'selected_task':'question';}changeTask();pickerOpen.value=false;active.value.notice=canRunExpert(expert)?'':expert.readiness?.runReasons?.join('；')||'当前专家暂不可执行，历史仍可阅读。'}
function removeExpert(){if(active.value.running)return;draft.value.expertId='';draft.value.taskId='';draft.value.input={}}
function upgradeExpert(){draft.value.upgradeToVersion=selectedExpert.value?.published?.version;active.value.notice='本轮将采用新发布版本；历史结果保持原版本。'}
function changeTask(){const fields=selectedTask.value?.inputSchema.properties||{},next:Record<string,unknown>={};for(const[key,field]of Object.entries(fields))if(draft.value.input[key]!=null)next[key]=draft.value.input[key];else if(field.default!=null)next[key]=field.default;draft.value.input=next;draft.value.originalTurnId=undefined;void loadCourses()}
async function load(){if(resourcesLoading.value)return;const requestEpoch=epoch;resourcesLoading.value=true;resourcesError.value='';try{const outcomes=await Promise.allSettled([api.catalog(),api.tasks(),api.models()]);if(requestEpoch!==epoch)return;if(outcomes[0].status==='fulfilled')catalog.value=outcomes[0].value;else resourcesError.value=(outcomes[0].reason as Error).message;if(outcomes[1].status==='fulfilled')tasks.value=outcomes[1].value.items;else {tasks.value=[];resourcesError.value=resourcesError.value||(outcomes[1].reason as Error).message||'业务任务加载失败。'}models.value=outcomes[2].status==='fulfilled'?outcomes[2].value.items:[];if(!resourcesError.value)void loadOptions()}finally{if(requestEpoch===epoch)resourcesLoading.value=false}}
async function loadOptions(){const requestEpoch=epoch;optionsLoading.value=true;optionsError.value='';try{const result=await api.options();if(requestEpoch===epoch)options.value={...result,courses:options.value.courses||[]}}catch(e){if(requestEpoch===epoch)optionsError.value=(e as Error).message}finally{if(requestEpoch===epoch)optionsLoading.value=false}}
async function loadCourses(){const request=++coursesEpoch,slot=active.value;coursesError.value='';options.value={...options.value,courses:[]};if(!selectedTask.value?.inputSchema.properties?.course_id||!slot.draft.input.semester_id){coursesLoading.value=false;return}coursesLoading.value=true;try{const result=await api.courseOptions(String(slot.draft.input.semester_id),String(slot.draft.input.college_id||'')||undefined);if(request!==coursesEpoch||slot!==active.value)return;options.value={...options.value,courses:result.items};if(slot.draft.input.course_id&&!result.items.some(c=>String(c.id)===String(slot.draft.input.course_id))){delete slot.draft.input.course_id;slot.notice='课程已不在新范围内，请重新确认。'}}catch(e){if(request===coursesEpoch)coursesError.value=(e as Error).message}finally{if(request===coursesEpoch)coursesLoading.value=false}}
async function loadHistory(reset=true){const request=++historyEpoch,requestEpoch=epoch;historyLoading.value=true;historyError.value='';try{const result=await api.researchList(historySearch.value,reset?0:history.value.length,30);if(request!==historyEpoch||requestEpoch!==epoch)return;const rows=Array.isArray(result)?result:result.items;history.value=reset?rows:[...history.value,...rows.filter(r=>!history.value.some(old=>old.id===r.id))];historyTotal.value=Array.isArray(result)?rows.length:result.total??history.value.length}catch(e){if(request===historyEpoch)historyError.value=(e as Error).message}finally{if(request===historyEpoch)historyLoading.value=false}}
async function openConversation(id:string){const requestEpoch=epoch;historyOpen.value=false;loadError.value='';try{if(!slots[id]){const research=await api.research(id);if(requestEpoch!==epoch)return;const initial=makeSlot();initial.research=research;initial.selected=(research.turns?.length||0)-1;const last=research.turns?.at(-1);initial.draft.expertId=String(last?.expert?.id||last?.expertId||research.expertId);initial.draft.taskId=tasks.value.find(t=>t.expertId===initial.draft.expertId&&t.available)?.taskId||'';slots[id]=initial;const slot=slots[id]!;const refId=last?.executionId||last?.execution?.executionId||last?.execution?.id;if(refId){slot.running=true;void poll(slot,String(refId),requestEpoch)}}currentKey.value=id;void loadCourses()}catch(e){if(requestEpoch===epoch)loadError.value=(e as Error).message}}
async function applyExecution(slot:Slot,value:ExpertExecution,requestEpoch:number){
  if(requestEpoch!==epoch)return
  const previous=slot.execution
  if(previous&&executionId(previous)===executionId(value)&&Number(value.revision||0)<Number(previous.revision||0))return
  slot.execution=value;if(value.submittedRequest)slot.pending=value.submittedRequest
  slot.submitting=false;slot.uncertain=false;slot.error=''
  const terminal=finalStates.has(value.state),working=!terminal||value.workerFinished===false
  slot.running=working
  if(value.researchId&&!slot.research){slots[value.researchId]=slot;for(const[key,item]of Object.entries(slots)){if(key.startsWith('pending:')&&item===slot){if(currentKey.value===key)currentKey.value=value.researchId;delete slots[key]}}}
  const changed=!previous||executionId(previous)!==executionId(value)||previous.revision!==value.revision
  if(value.researchId&&(!slot.research||terminal&&changed)){
    const selectedId=slot.research?.turns?.[slot.selected]?.id
    const research=await api.research(value.researchId);if(requestEpoch!==epoch)return
    slot.research=research
    const selectedIndex=selectedId?research.turns?.findIndex(turn=>turn.id===selectedId):-1
    const firstTerminal=terminal&&(!previous||!finalStates.has(previous.state))
    slot.selected=!firstTerminal&&selectedIndex!=null&&selectedIndex>=0?selectedIndex:(research.turns?.length||0)-1
    void loadHistory(true)
  }
  if(terminal){slot.notice=['completed','partial'].includes(value.state)?`本轮事实已保存。${explanationStateLabel(value.explanationState)}${working?'，工作进程结束后可发送下一轮。':'。'}`:value.summary||stateLabel(value.state)}
  clearTimeout(timers.get(slot));timers.delete(slot)
  if(working)timers.set(slot,setTimeout(()=>void poll(slot,executionId(value),requestEpoch),1300))
}
async function poll(slot:Slot,id:string,requestEpoch:number){try{await applyExecution(slot,await api.execution(id),requestEpoch)}catch(e){if(requestEpoch!==epoch)return;slot.running=false;slot.uncertain=true;slot.error=`状态尚未确认，任务可能仍在执行。${(e as Error).message}`}}
async function submit(slot:Slot,request:ConversationRequest,clearText=false){if(slot.running||slot.submitting||slot.uncertain)return;const requestEpoch=epoch,text=slot.draft.question;slot.submitting=true;slot.running=true;slot.error='';slot.notice='';slot.pending=request;slot.execution=null;if(slots.new===slot){const key=`pending:${request.clientRequestId}`;slots[key]=slot;slots.new=makeSlot();if(currentKey.value==='new')currentKey.value=key}try{const value=await api.execute(request);if(requestEpoch!==epoch)return;if(clearText&&slot.draft.question===text)slot.draft.question='';await applyExecution(slot,value,requestEpoch)}catch(e){if(requestEpoch===epoch){slot.running=false;slot.submitting=false;slot.uncertain=true;slot.error=`提交结果未确认，请先查询原请求。${(e as Error).message}`}}}
async function send(){if(!canSend.value)return;const slot=active.value;await submit(slot,{clientRequestId:crypto.randomUUID(),expertId:slot.draft.expertId,researchId:slot.research?.id,expectedTurn:slot.research?.turns?.length||0,expertSelection:'per_turn',upgradeToVersion:slot.draft.upgradeToVersion,mode:slot.draft.mode,question:slot.draft.question.trim()||selectedTask.value?.title||'说明保存结果',input:slot.draft.readMode==='saved'?{}:slot.draft.mode==='selected_task'?{...slot.draft.input,taskId:slot.draft.taskId}:{...slot.draft.input},readMode:slot.draft.readMode,publicationId:slot.draft.source?.publicationId,sourceResultId:slot.draft.source?.resultId,objectId:slot.draft.source?.objectId,originalTurnId:slot.draft.originalTurnId},true)}
async function recover(){const slot=active.value;if(!slot.pending)return;const requestEpoch=epoch;slot.submitting=true;try{const found=await api.executionRequest(slot.pending.clientRequestId);if(requestEpoch!==epoch)return;slot.submitting=false;if(found.found&&found.execution){await applyExecution(slot,found.execution,requestEpoch)}else{slot.running=false;slot.uncertain=false;slot.pending=null;slot.error='';slot.notice='服务器确认原请求尚未受理。草稿已保留，请调整条件后发送新请求。'}}catch(e){if(requestEpoch===epoch){slot.submitting=false;slot.uncertain=true;slot.error=`原请求仍无法确认：${(e as Error).message}`}}}
async function retry(){const slot=active.value;if(!slot.pending||!canRetry.value)return;slot.notice=`由原专家${slot.execution?.expertId||slot.pending.expertId}按原范围重试。`;await submit(slot,{...slot.pending,clientRequestId:crypto.randomUUID(),researchId:slot.research?.id||slot.execution?.researchId,expectedTurn:slot.research?.turns?.length||0,retryOfExecutionId:executionId(slot.execution)})}
async function cancel(){const slot=active.value,id=executionId(slot.execution);if(!id)return;try{await applyExecution(slot,await api.cancelExecution(id),epoch)}catch(e){slot.error=(e as Error).message}}
async function answerClarification(){const slot=active.value,c=clarification.value;if(!c||!slot.execution||!slot.answer.trim()||!slot.pending)return;await submit(slot,{...slot.pending,clientRequestId:crypto.randomUUID(),researchId:slot.execution.researchId,expectedTurn:slot.research?.turns?.length||0,mode:'clarification_answer',originalTurnId:slot.execution.turnId,clarificationId:c.clarificationId,answer:slot.answer,input:{}});slot.answer=''}
function onComposerKey(event:Event|KeyboardEvent){if(event instanceof KeyboardEvent&&event.key==='Enter'&&event.ctrlKey&&!event.isComposing){event.preventDefault();void send()}}
function prepareCourse(row:Record<string,unknown>){if(active.value.running||!selectedRun.value)return;const turn=selectedRun.value;draft.value.expertId=turn.expert?.id||turn.expertId||active.value.research?.expertId||'';draft.value.taskId='C-PERFORMANCE';draft.value.input={...turn.input,course_id:String(row.course_id)};draft.value.mode='selected_task';draft.value.readMode='live';draft.value.question=draft.value.question||`查看${row.course_name||row.course_id}当前首修表现`;draft.value.originalTurnId=undefined;resultOpen.value=false;active.value.notice='已准备单课的新查询范围，确认后发送。'}
function prepareRecheck(id?:string){const turn=turns.value.find(t=>t.id===id)||selectedRun.value;if(!turn)return;if(active.value.running)return;draft.value.expertId=turn.expert?.id||turn.expertId||active.value.research?.expertId||'';draft.value.taskId=String(turn.input?.taskId||'');draft.value.input={...turn.input};draft.value.question=draft.value.question||turn.question||'';draft.value.originalTurnId=turn.id;draft.value.mode='selected_task';draft.value.readMode='live';issuesOpen.value=false;active.value.notice='已准备原问题、原专家与范围，确认补充条件后发送。'}
function clearSource(){draft.value.source=undefined;draft.value.readMode='live'}
function returnToBriefing(){const id=draft.value.source?.publicationId;if(id)void router.push({path:'/admin/reports/decision',query:{publicationId:id}})}
async function prepareReference(){const id=String(route.query.publicationId||'');if(!id)return;const requestEpoch=epoch;try{const publication=await api.publication(id);if(requestEpoch!==epoch)return;if(publication.applicable===false||publication.state==='withdrawn'||publication.status==='withdrawn'){loadError.value='这份简报已失效，不能作为本轮有效事实引用。';return}const slot=slots.new!;currentKey.value='new';const objectId=String(route.query.objectId||'');slot.draft.source={publicationId:id,resultId:publication.resultId,objectId,name:publication.name,objectName:String(route.query.objectName||'')};const original=publication.run?.submittedRequest;slot.draft.expertId=original?.expertId||publication.expertId||tasks.value.find(t=>t.taskId==='C-PERFORMANCE')?.expertId||'';slot.draft.taskId=String(original?.input?.taskId||'C-PERFORMANCE');const schema=tasks.value.find(task=>task.taskId===slot.draft.taskId&&task.expertId===slot.draft.expertId)?.inputSchema;const sourceInput=original?.input||publication.input||publication.outcome?.result?.scope||{};slot.draft.input={};for(const field of Object.keys(schema?.properties||{}))if(field!=='taskId'&&sourceInput[field]!=null)slot.draft.input[field]=sourceInput[field];slot.draft.readMode='saved';const prepared=String(route.query.question||'说明这门课程为什么进入观察范围，并说明数据依据和判断边界。');if(slot.draft.question.trim()){slot.notice='已附上简报引用；现有草稿保留，可自行补充问题。'}else slot.draft.question=prepared;}catch(e){if(requestEpoch===epoch)loadError.value=`简报引用无法读取：${(e as Error).message}`}}
function resetIdentity(){epoch++;for(const timer of timers.values())clearTimeout(timer);timers.clear();for(const key of Object.keys(slots))delete slots[key];slots.new=makeSlot();currentKey.value='new';history.value=[];historyTotal.value=0;catalog.value={experts:[],skills:[],mcps:[]};tasks.value=[];models.value=[];options.value={plans:[],semesters:[],colleges:[],courses:[]};pickerOpen.value=false;resultOpen.value=false;issuesOpen.value=false;loadError.value='';resourcesError.value='';resourcesLoading.value=false;if(authStore.user){void load();void loadHistory(true)}}
watch(historySearch,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>void loadHistory(true),300)})
watch(()=>[draft.value.input.semester_id,draft.value.input.college_id,draft.value.taskId,currentKey.value],()=>void loadCourses())
watch(()=>[authStore.user?.username,authStore.user?.activeIdentityId,authStore.user?.permissionContext?.scopeFingerprint].join('|'),resetIdentity)
watch(()=>route.query.publicationId,()=>void prepareReference())
watch(()=>route.query.researchId,id=>{if(id&&String(id)!==active.value.research?.id)void openConversation(String(id))})
onMounted(async()=>{await load();void loadHistory(true);const expertId=String(route.query.expertId||'');if(expertId){const expert=catalog.value.experts.find(e=>e.id===expertId);if(expert)selectExpert(expert)}await prepareReference();const researchId=String(route.query.researchId||'');if(researchId)void openConversation(researchId)})
onBeforeUnmount(()=>{epoch++;for(const timer of timers.values())clearTimeout(timer);clearTimeout(searchTimer)})
</script>

